<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {watchHostTheme} from './theme.js'
const props=defineProps({api:Object,pluginId:{type:String,default:'ForumSignin'},show_switch:{type:Boolean,default:true}})
const emit=defineEmits(['close','switch','layout'])
const stats=ref(null),history=ref({total:0,items:[]}),error=ref(''),busy=ref(false)
const labels={success:'成功',signed:'已签',failed:'失败',auth_failed:'认证失败',unconfirmed:'未确认',network_error:'网络异常',skipped:'跳过',disabled:'停用'}
const stateClass=s=>['success','signed'].includes(s)?'success':['failed','auth_failed'].includes(s)?'failure':['unconfirmed','network_error'].includes(s)?'unknown':'off'
const counts=computed(()=>stats.value?.today||{})
const days=computed(()=>{const map=new Map();for(const item of history.value.items){const date=formatTime(item.time).slice(0,10);if(!map.has(date))map.set(date,{date,records:[]});map.get(date).records.push(item)}return [...map.values()].sort((a,b)=>b.date.localeCompare(a.date))})
function formatTime(v){if(!v)return '';const d=new Date(v);if(Number.isNaN(d.getTime()))return v;return `${d.getFullYear()}/${String(d.getMonth()+1).padStart(2,'0')}/${String(d.getDate()).padStart(2,'0')} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}:${String(d.getSeconds()).padStart(2,'0')}`}
async function get(path){const r=await props.api.get(`plugin/${props.pluginId}/${path}`);if(r?.success===false)throw Error(r.message);return r?.data??r}
async function loadHistory(){const first=await get('history?page=1&size=100');const items=[...(first.items||[])];for(let page=2;items.length<first.total;page++){const next=await get(`history?page=${page}&size=100`);if(!next.items?.length)break;items.push(...next.items)}return {total:first.total,items}}
async function load(){error.value='';try{[stats.value,history.value]=await Promise.all([get('stats'),loadHistory()])}catch(e){error.value=e.message||'加载失败'}}
async function action(path){busy.value=true;error.value='';try{const r=await props.api.post(`plugin/${props.pluginId}/${path}`,{auth:'bear'});if(r?.success===false)throw Error(r.message);await load()}catch(e){error.value=e.message||'执行失败'}finally{busy.value=false}}
let stopTheme;onMounted(()=>{stopTheme=watchHostTheme();load();emit('layout',{maxWidth:'1000px'})});onBeforeUnmount(()=>stopTheme?.())
</script>
<template><div class="pt-center"><section class="card embedded-card" aria-label="论坛签到数据"><div class="card-head"><h2>论坛签到</h2><div class="row"><button v-if="show_switch" class="btn ghost" @click="emit('switch')">配置</button><button class="btn ghost" @click="emit('close')">关闭</button></div></div>
<div v-if="error" class="alert" role="alert">{{error}}</div><div v-if="stats" class="win"><div class="topline"><h3>今日总览</h3><div class="row"><span class="hint">下次调度：{{formatTime(stats.next_schedule)||'未设置'}}</span><button class="btn" :disabled="busy" @click="action('run_once')">立即运行</button><button class="btn ghost" :disabled="busy" @click="action('clean_cache')">清理缓存</button></div></div>
<div class="stats"><div v-for="(label,key) in {success:'成功',failed:'失败',unconfirmed:'未确认'}" :key="key" class="stat" :class="stateClass(key)"><strong>{{counts[key]||0}}</strong><span>{{label}}</span></div></div><div class="data-grid"><article v-for="site in stats.sites||[]" :key="site.id" class="site-card"><div class="site-head"><strong class="site-label"><span class="site-icon site-initial">{{site.name?.slice(0,1)}}</span>{{site.name}}</strong><span class="chip" :class="stateClass(site.status)">{{labels[site.status]||'未运行'}}</span><button class="btn ghost mini" :aria-label="`测试连接 ${site.name}`" @click="action('verify_site?domain='+encodeURIComponent(site.domain))">🔗</button></div><div class="badges"><span v-if="site.enabled" class="chip success">启用</span><span v-if="site.signin_capable" class="chip badge-signin">签到</span><span v-if="site.login_capable" class="chip badge-login">登录</span></div><div class="site-totals"><span><b class="success-number">{{stats.site_counts?.[site.id]?.success||0}}</b> 成功</span><span><b class="failure-number">{{stats.site_counts?.[site.id]?.failed||0}}</b> 失败</span><span><b class="unknown-number">{{stats.site_counts?.[site.id]?.unconfirmed||0}}</b> 未确认</span></div><p v-if="site.message" class="meta">{{site.message}}</p></article></div><h3>历史记录</h3></div>
<div class="table-wrap"><details v-for="group in days" :key="group.date" class="history-group" :open="group.date===formatTime(new Date()).slice(0,10)"><summary class="history-summary">▸ {{group.date}} · {{group.records.length}} 条 · 成功 {{group.records.filter(x=>['success','signed'].includes(x.status)).length}} / 失败 {{group.records.filter(x=>['failed','auth_failed'].includes(x.status)).length}} / 未确认 {{group.records.filter(x=>['unconfirmed','network_error'].includes(x.status)).length}}</summary><table><thead><tr><th>时间</th><th>论坛</th><th>状态</th><th>最近消息</th></tr></thead><tbody><tr v-for="item in group.records" :key="item.time+item.site"><td>{{formatTime(item.time)}}</td><td>{{item.site}}</td><td><span class="chip" :class="stateClass(item.status)">{{labels[item.status]||item.status}}</span></td><td>{{[item.message,item.reward?.reported].filter(Boolean).join(' / ')}}</td></tr></tbody></table></details><div v-if="!history.items.length" class="empty">暂无历史记录</div></div></section></div></template>
<style scoped src="./preview.css"></style>
